const r = await tools.exec_command({"cmd":"CUDA_VISIBLE_DEVICES=0 python - <<'PY'
import sys, hashlib, json, math
from pathlib import Path
import numpy as np, torch
sys.path.insert(0,'candidates')
import sequence_probe as s
import bge_probe as b
root=Path('input/competition/dataset')
tr=s.read_jsonl(root/'train/data.jsonl'); dv=s.read_jsonl(root/'dev/data.jsonl')
ta={r['id']:int(r['boundary_char_index']) for r in s.read_jsonl(root/'train/answers.jsonl')}; da={r['id']:int(r['boundary_char_index']) for r in s.read_jsonl(root/'dev/answers.jsonl')}
fr=np.array([ta[r['id']]/len(r['text']) for r in tr]); pm,ps=fr.mean(),fr.std(ddof=1)
bundle=s.fit_origin_model(tr,ta,100000,2.0)
LP=[]; LD=[]
for row in dv:
 st,se=s.starts_and_sentences(row['text']); z=np.asarray(s.origin_scores(bundle,se)); obj=np.cumsum(z[::-1])[::-1]+.3*(-.5*((np.array(st)/len(row['text'])-pm)/ps)**2); valid=np.arange(1,len(st)); k=valid[np.argmax(obj[valid])]; alt=np.delete(valid,np.argmax(obj[valid])); far=valid[np.abs(valid-k)>=2];
 LP.append(st[k]); LD.append(dict(n=len(st), k=int(k), frac=st[k]/len(row['text']), margin=float(obj[k]-np.max(obj[alt])) if len(alt) else 99, far_margin=float(obj[k]-np.max(obj[far])) if len(far) else 99, seam=float(min(-z[k-1],z[k])) if k<len(z) else -99, left=float(z[:k].mean()),right=float(z[k:].mean()), violation=float(np.mean(z[:k]>0)+np.mean(z[k:]<0))))
# bge exact predictions + confidence
trtxt,trm=b.flatten_rows(tr); dvtxt,dvm=b.flatten_rows(dv); emb,_=b.embed_texts(trtxt+dvtxt,Path('input/competition/models/bge-base-en-v1.5'),192,96,torch.device('cuda:0')); te,de=emb[:len(trtxt)],emb[len(trtxt):]
y,w,bf=b.sentence_labels(tr,ta,trm); clf=b.fit_emission_model(te,y,w,2.); logits=clf.decision_function(de)
BP=[]; BD=[]
for row,(st,sl) in zip(dv,dvm):
 z=logits[sl]; valid=np.arange(1,len(st)); emis=np.concatenate(([0.],np.cumsum(-z)))[valid]; pri=-.5*((np.array(st)[valid]/len(row['text'])-bf.mean())/bf.std())**2; obj=emis+pri; ii=np.argmax(obj); k=valid[ii]; alt=np.delete(obj,ii); far=obj[np.abs(valid-k)>=2]
 BP.append(st[k]); BD.append(dict(margin=float(obj[ii]-alt.max()) if len(alt) else 99,far_margin=float(obj[ii]-far.max()) if len(far) else 99,seam=float(min(-z[k-1],z[k])) if k<len(z) else -99))
truth=np.array([da[r['id']] for r in dv]); lp=np.array(LP); bp=np.array(BP); le=np.abs(lp-truth); be=np.abs(bp-truth)
metric=lambda e:100*np.exp(-e/100).mean()
print('BASE',metric(le),metric(be),'agree',np.mean(lp==bp),'agree_exact',np.mean((lp==bp)&(le==0)))
print('outcomes lex/bge exact',[(a,c,int(np.sum((le==0)==a & ((be==0)==c)))) for a in []])
for name,mask in [('agree',lp==bp),('disagree',lp!=bp),('lexbad100',le>100),('lexcat300',le>300)]:
 print(name,mask.sum(),'lex',metric(le[mask]) if mask.any() else 0,'bge',metric(be[mask]) if mask.any() else 0,'lex_exact',np.mean(le[mask]==0) if mask.any() else 0,'bge_exact',np.mean(be[mask]==0) if mask.any() else 0)
print('pair cases lex_exact/bge_exact')
for a in (0,1):
 for c in (0,1):
  m=((le==0)==a)&((be==0)==c); print(a,c,m.sum(),metric(le[m]) if m.any() else 0,metric(be[m]) if m.any() else 0)
# fixed hash halves
half=np.array([int(hashlib.sha256(r['id'].encode()).hexdigest(),16)%2 for r in dv])
for h in (0,1):
 m=half==h;print('half',h,m.sum(),metric(le[m]),metric(be[m]))
# slices
lens=np.array([len(r['text']) for r in dv]); tf=np.array([da[r['id']]/len(r['text']) for r in dv]);
for arr,lab in [(lens,'length'),(tf,'truefrac')]:
 q=np.quantile(arr,[.25,.75]);
 for name,m in [('low',arr<=q[0]),('mid',(arr>q[0])&(arr<q[1])),('high',arr>=q[1])]: print('slice',lab,name,m.sum(),metric(le[m]),metric(be[m]))
# confidence bins and catastrophic examples
for key in ['margin','far_margin','seam','violation','frac']:
 x=np.array([d[key] for d in LD]); qs=np.quantile(x,[.2,.4,.6,.8]); print('CONF',key,'q',qs)
 for j,m in enumerate([x<=qs[0],(x>qs[0])&(x<=qs[1]),(x>qs[1])&(x<=qs[2]),(x>qs[2])&(x<=qs[3]),x>qs[3]]): print(j,m.sum(),metric(le[m]),np.mean(le[m]==0),np.mean(le[m]>300),metric(be[m]))
print('CATASTROPHIC')
for i in np.argsort(-le)[:20]:
 print(dv[i]['id'],len(dv[i]['text']),truth[i],lp[i],bp[i],le[i],be[i],LD[i],BD[i])
# bge fallback threshold simple per dev halves scan and cross-evaluate
x=np.array([d['far_margin'] for d in LD]);
for trainh,testh in [(0,1),(1,0)]:
 best=None
 for th in np.quantile(x[half==trainh],np.linspace(0,.5,21)):
  for reqagreeprior in [False]:
   pred=np.where(x<th,bp,lp); sc=metric(np.abs(pred[half==trainh]-truth[half==trainh]));
   if best is None or sc>best[0]:best=(sc,th)
 sc2=metric(np.abs(np.where(x<best[1],bp,lp)[half==testh]-truth[half==testh]));print('cross',trainh,testh,best,'test',sc2)
PY","workdir":"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project","yield_time_ms":30000,"max_output_tokens":30000}); text(JSON.stringify(r))

